// AUTHORED-BY Claude Fable 5.2
// Use cases view (the catalogue, where structure struggles, coverage) and the evaluation plan
// shown above the test matrix. Data: data/use-cases.json, generated by scripts/use-cases.src.py.
// Classic script; loads after views.js.
(function () {
  'use strict';
  var AX = window.AX;
  var esc = AX.esc;
  var R = (AX.render = AX.render || {});
  var D = AX.data.useCases;
  if (!D) return;

  var U = D.useCases;
  var byId = {};
  U.forEach(function (u) { byId[u.id] = u; });
  function index(list) { var m = {}; list.forEach(function (x) { m[x.id] = x; }); return m; }
  var SECTOR = index(D.sectors), SETTING = index(D.settings), FIT = index(D.fits), STRAIN = index(D.strains), BENCH = index(D.benchmarks);
  var FIT_CLS = { fits: 'pass', strains: 'ask', breaks: 'fail' };
  var OUT = { go: ['Go', 'pass'], stop: ['Stop', 'fail'], 'ask-principal': ['Ask the principal', 'askp'], 'ask-more': ['Ask for more', 'ask'] };
  var KEYS = ['sector', 'setting', 'fit', 'strain', 'bench', 'run'];

  function hash(p, change) {
    var q = { tab: p.tab };
    KEYS.forEach(function (k) { if (p[k]) q[k] = p[k]; });
    Object.keys(change || {}).forEach(function (k) { if (change[k]) q[k] = change[k]; else delete q[k]; });
    return AX.buildHash('usecases', q);
  }
  function matches(u, p) {
    return (!p.sector || u.sector === p.sector) && (!p.setting || u.setting === p.setting) && (!p.fit || u.fit === p.fit) &&
      (!p.strain || u.strains.indexOf(p.strain) >= 0) && (!p.bench || u.benchmarks.indexOf(p.bench) >= 0) &&
      (!p.run || (p.run === 'yes') === isRun(u));
  }
  function fitTag(u) { return '<span class="pill v-' + FIT_CLS[u.fit] + ' fit-pill">' + esc(FIT[u.fit].name) + '</span>'; }
  function traceFor(u) {
    if (!u.trace) return null;
    return AX.traces.filter(function (t) { return t.scenario && t.scenario.id === u.trace && !t.isFixture; })[0] ||
      AX.traces.filter(function (t) { return t.scenario && t.scenario.id === u.trace; })[0] || null;
  }
  function isRun(u) { var t = traceFor(u); return u.status === 'worked' && !!t && !t.isFixture; }
  function runTag(u) {
    var t = traceFor(u);
    if (isRun(u)) return '<span class="tag ok">Real run</span>';
    return '<span class="tag">Not run yet</span>';
  }

  function useCase(u, open) {
    var h = '<details class="uc" id="uc-' + esc(u.id) + '"' + (open ? ' open' : '') + '><summary>';
    h += '<span class="uc-title">' + esc(u.title) + '</span>';
    h += '<span class="uc-meta"><span class="chip quiet">' + esc(SECTOR[u.sector].name) + '</span><span class="chip quiet">' + esc(SETTING[u.setting].name) + '</span>' + fitTag(u) + runTag(u) + '</span>';
    h += '</summary><div class="uc-body">';
    h += '<p>' + esc(u.story) + '</p>';
    h += '<p><strong>What makes it hard.</strong> ' + esc(u.hard) + '</p>';
    if (u.fitNote) h += '<p><strong>' + esc(FIT[u.fit].name) + '.</strong> ' + esc(u.fitNote) + '</p>';
    h += '<h4>What goes wrong, and what the agent does</h4><ul class="outcome-list">';
    u.branches.forEach(function (b) {
      var o = OUT[b.outcome];
      h += '<li><span class="pill v-' + o[1] + '">' + esc(o[0]) + '</span><span>' + esc(b.what) + '</span><span class="t"><code>' + esc(b.reason) + '</code></span></li>';
    });
    h += '</ul><dl class="uc-facts">';
    h += '<dt>Who is involved</dt><dd>' + u.parties.map(esc).join(', ') + '</dd>';
    h += '<dt>Checks that carry the weight</dt><dd class="chips">' + u.stress.map(function (c) {
      var ck = AX.checkById[c];
      return '<span class="chip">' + esc(ck ? ck.name : c) + '</span>';
    }).join('') + '</dd>';
    var sw = Object.keys(u.suites);
    if (sw.length) {
      h += '<dt>Beyond the baseline</dt><dd class="chips">' + sw.map(function (l) {
        return '<a class="chip" href="' + AX.buildHash('layers', { select: l }) + '">' + esc(AX.layerById[l].name) + ': ' + esc(AX.suiteName(l, u.suites[l])) + '</a>';
      }).join('') + '</dd>';
    }
    if (u.assurance) {
      var a = AX.model.derivation.assurances.filter(function (x) { return x.id === u.assurance; })[0];
      h += '<dt>Sends an answer, not the records</dt><dd><a href="' + AX.buildHash('message', { at: 'derived' }) + '">' + esc(a.name) + '</a></dd>';
    }
    if (u.strains.length) {
      h += '<dt>Where structure struggles</dt><dd class="chips">' + u.strains.map(function (s) {
        return '<a class="chip" href="' + AX.buildHash('usecases', { tab: 'struggles', at: 'strain-' + s }) + '">' + esc(STRAIN[s].name) + '</a>';
      }).join('') + '</dd>';
    }
    if (u.benchmarks.length) {
      h += '<dt>Published benchmarks that test this</dt><dd class="chips">' + u.benchmarks.map(function (b) {
        return '<a class="chip" href="' + AX.buildHash('tests', { at: 'bench-' + b }) + '">' + esc(BENCH[b].name) + '</a>';
      }).join('') + '</dd>';
    }
    h += '</dl>';
    var t = traceFor(u);
    if (t) h += '<p><a class="btn" href="' + AX.buildHash('explore', { scenario: t.scenario.id, config: t.configuration.id }) + '">Step through ' + (t.isFixture ? 'the mock-up' : 'the real run') + '</a></p>';
    h += '</div></details>';
    return h;
  }

  function filterRow(label, key, items, p) {
    var h = '<div class="filter-row"><span class="filter-label">' + esc(label) + '</span><span class="chips">';
    h += '<a class="chip' + (!p[key] ? ' on' : ' quiet') + '" href="' + hash(p, objOf(key, '')) + '">All</a>';
    items.forEach(function (it) {
      var n = U.filter(function (u) { var q = {}; KEYS.forEach(function (k) { q[k] = p[k]; }); q[key] = it.id; return matches(u, q); }).length;
      h += '<a class="chip' + (p[key] === it.id ? ' on' : ' quiet') + (n ? '' : ' none') + '" href="' + hash(p, objOf(key, p[key] === it.id ? '' : it.id)) + '">' + esc(it.name) + ' <small>' + n + '</small></a>';
    });
    return h + '</span></div>';
  }
  function objOf(k, v) { var o = {}; o[k] = v; return o; }

  function catalogue(p) {
    var shown = U.filter(function (u) { return matches(u, p); });
    var h = '<div class="filters">';
    h += filterRow('Setting', 'setting', D.settings, p);
    h += filterRow('Sector', 'sector', D.sectors, p);
    h += filterRow('Fit', 'fit', D.fits, p);
    h += filterRow('Run', 'run', [{ id: 'yes', name: 'Real run' }, { id: 'no', name: 'Not run yet' }], p);
    h += '</div>';
    var extra = [];
    if (p.strain && STRAIN[p.strain]) extra.push('struggle: ' + STRAIN[p.strain].name);
    if (p.bench && BENCH[p.bench]) extra.push('benchmark: ' + BENCH[p.bench].name);
    h += '<p class="small muted uc-count">Showing ' + shown.length + ' of ' + U.length + (extra.length ? ' (' + esc(extra.join('; ')) + ', <a href="' + hash(p, { strain: '', bench: '' }) + '">clear</a>)' : '') + '</p>';
    var openId = p.at && p.at.indexOf('uc-') === 0 ? p.at.slice(3) : null;
    h += shown.length ? shown.map(function (u) { return useCase(u, u.id === openId); }).join('') : '<p class="empty">No use case matches these filters.</p>';
    return h;
  }

  function struggles() {
    var h = '<p class="lede" style="margin-bottom:18px">Messages in agreed terms are easy to check and cannot say everything. These are the ' + D.strains.length + ' ways the catalogue found them falling short, what the design does about each, and what it leaves unsolved. The rules are in <a href="' + AX.buildHash('specs', { doc: '04-unstructured-content' }) + '">Content that does not fit</a>.</p>';
    D.strains.forEach(function (s) {
      h += '<section class="card strain" id="strain-' + esc(s.id) + '"><h3>' + esc(s.name) + '</h3>';
      h += '<p>' + esc(s.problem) + '</p>';
      h += '<div class="strain-grid"><div><h4>What the design does</h4><p>' + esc(s.response) + '</p></div><div><h4>What stays unsolved</h4><p>' + esc(s.limit) + '</p></div></div>';
      h += '<p class="chips" style="margin-top:10px">' + s.examples.map(function (id) {
        return '<a class="chip" href="' + AX.buildHash('usecases', { tab: 'catalogue', strain: s.id, at: 'uc-' + id }) + '">' + esc(byId[id].title) + '</a>';
      }).join('') + '</p></section>';
    });
    return h;
  }

  function coverage() {
    var h = '<p class="lede" style="margin-bottom:18px">Where the catalogue is thick and where it is thin. Each cell counts use cases; the dots show how well structured messages cope.</p>';
    h += '<div class="table-wrap"><table class="data cov"><thead><tr><th>Sector</th>' + D.settings.map(function (s) { return '<th title="' + esc(s.summary) + '">' + esc(s.name) + '</th>'; }).join('') + '<th>All</th></tr></thead><tbody>';
    function cell(list, href) {
      if (!list.length) return '<td class="cov-none">·</td>';
      return '<td><a href="' + href + '"><b>' + list.length + '</b> ' + list.map(function (u) { return '<i class="fdot v-' + FIT_CLS[u.fit] + '" title="' + esc(u.title + ': ' + FIT[u.fit].name) + '"></i>'; }).join('') + '</a></td>';
    }
    D.sectors.forEach(function (sec) {
      h += '<tr><th scope="row">' + esc(sec.name) + '</th>';
      D.settings.forEach(function (st) {
        h += cell(U.filter(function (u) { return u.sector === sec.id && u.setting === st.id; }), AX.buildHash('usecases', { tab: 'catalogue', sector: sec.id, setting: st.id }));
      });
      h += cell(U.filter(function (u) { return u.sector === sec.id; }), AX.buildHash('usecases', { tab: 'catalogue', sector: sec.id })) + '</tr>';
    });
    h += '<tr class="cov-total"><th scope="row">All</th>' + D.settings.map(function (st) {
      return cell(U.filter(function (u) { return u.setting === st.id; }), AX.buildHash('usecases', { tab: 'catalogue', setting: st.id }));
    }).join('') + cell(U, AX.buildHash('usecases', { tab: 'catalogue' })) + '</tr></tbody></table></div>';

    var checks = (AX.model.inboundChecks || []).concat(AX.model.outboundChecks || []);
    var max = 1;
    var counts = checks.map(function (c) { var n = U.filter(function (u) { return u.stress.indexOf(c.id) >= 0; }).length; if (n > max) max = n; return n; });
    h += '<h2>Which checks carry the weight</h2><p class="small muted">The number of use cases in which each check is one of those that decide the outcome.</p><div class="bars">';
    checks.forEach(function (c, i) {
      h += '<div class="bar-row"><span class="bar-name">' + esc(c.name) + ' <small>' + (c.gate === 'inbound-gate' ? 'in' : 'out') + '</small></span><span class="bar-track"><span class="bar" style="width:' + Math.round(100 * counts[i] / max) + '%"></span></span><span class="bar-n">' + counts[i] + '</span></div>';
    });
    h += '</div>';

    var ass = AX.model.derivation.assurances;
    h += '<h2>Answers instead of records</h2><p class="small muted">' + U.filter(function (u) { return u.assurance; }).length + ' use cases send a derived answer. How the answer is assured:</p><p class="chips">' + ass.map(function (a) {
      return '<span class="chip">' + esc(a.name) + ' <small>' + U.filter(function (u) { return u.assurance === a.id; }).length + '</small></span>';
    }).join('') + '</p>';
    h += '<h2>What is missing</h2><p style="max-width:72ch">No case yet for physical devices, for children as principals, for voice, or for acting for someone who has died. Few cases outside the kinds of register Europe has. These are gaps in the catalogue, not claims that the design covers them.</p>';
    return h;
  }

  R.usecases = function (root, p) {
    var tab = ['catalogue', 'struggles', 'coverage'].indexOf(p.tab) >= 0 ? p.tab : 'catalogue';
    p.tab = tab;
    var nRun = U.filter(isRun).length;
    var h = '<div class="page"><header><p class="eyebrow">Use cases</p><h1>' + U.length + ' situations, one design</h1>';
    h += '<p class="lede">The mortgage is one example. This catalogue asks the same questions of ' + U.length + ' situations in ' + D.sectors.length + ' sectors, from a hospital referral to two strangers sharing a flat: what makes it hard, what goes wrong, and whether messages in agreed terms are enough. Everyone in it is fictional. ' + nRun + ' of ' + U.length + ' has a real run so far.</p></header>';
    h += '<div class="fit-tiles">' + D.fits.map(function (f) {
      var n = U.filter(function (u) { return u.fit === f.id; }).length;
      return '<a class="fit-tile v-' + FIT_CLS[f.id] + (p.fit === f.id ? ' on' : '') + '" href="' + AX.buildHash('usecases', { tab: 'catalogue', fit: p.fit === f.id ? '' : f.id }) + '"><span class="n">' + n + '</span><span class="nm">' + esc(f.name) + '</span><span class="sm">' + esc(f.summary) + '</span></a>';
    }).join('') + '</div>';
    h += '<div class="tabs" role="tablist">' + [['catalogue', 'The catalogue'], ['struggles', 'Where structure struggles'], ['coverage', 'Coverage']].map(function (t) {
      return '<a role="tab" href="' + AX.buildHash('usecases', { tab: t[0] }) + '"' + (tab === t[0] ? ' aria-selected="true"' : '') + '>' + t[1] + '</a>';
    }).join('') + '</div>';
    h += tab === 'catalogue' ? catalogue(p) : tab === 'struggles' ? struggles() : coverage();
    h += '</div>';
    root.innerHTML = h;
  };

  // ---- Evaluation plan, shown above the test matrix ---------------------------------------
  var E = D.evaluation;
  var METHOD = index(E.methods);
  var baseTests = R.tests;
  R.tests = function (root, p) {
    if (baseTests) baseTests(root, p); else root.innerHTML = '<div class="page"></div>';
    var page = root.querySelector('.page');
    var head = page.querySelector('header');
    var runsHtml = '';
    if (head) {
      head.remove();
      runsHtml = page.innerHTML;
    }
    var nRun = U.filter(isRun).length;
    var h = '<header><p class="eyebrow">Evaluation</p><h1>How we know it works</h1><p class="lede">The design promises that an agent does only what its principal allowed, reveals no more than a task needs, relies only on what it has reason to, and leaves a record that shows who was at fault. This page is the plan for testing each promise and its cost, and the runs so far. No number appears here until a run has produced it.</p></header>';
    h += '<h2 id="questions">Ten questions</h2><div class="table-wrap"><table class="data"><thead><tr><th>Question</th><th>What is measured</th><th>How</th></tr></thead><tbody>';
    E.questions.forEach(function (q) {
      h += '<tr><td><strong>' + esc(q.question) + '</strong></td><td>' + esc(q.measure) + '</td><td><a href="' + AX.buildHash('tests', { at: 'method-' + q.method }) + '">' + esc(METHOD[q.method].name) + '</a></td></tr>';
    });
    h += '</tbody></table></div>';
    h += '<h2>Methods</h2><div class="cards two">' + E.methods.map(function (m) {
      return '<section class="card" id="method-' + esc(m.id) + '"><h3>' + esc(m.name) + ' <span class="tag' + (m.needsModel ? ' fx' : ' ok') + '">' + (m.needsModel ? 'Needs a model' : 'No model needed') + '</span></h3><p>' + esc(m.summary) + '</p></section>';
    }).join('') + '</div>';
    h += '<h2 id="benchmarks">Published benchmarks</h2><p class="small muted" style="max-width:72ch">Existing tasks and attacks, so the test is not only one we wrote. Counts are as reported by each benchmark\'s authors.</p><div class="table-wrap"><table class="data"><thead><tr><th>Benchmark</th><th>Used for</th><th>How it maps onto the design</th><th>Use cases</th></tr></thead><tbody>';
    D.benchmarks.forEach(function (b) {
      var n = U.filter(function (u) { return u.benchmarks.indexOf(b.id) >= 0; }).length;
      h += '<tr id="bench-' + esc(b.id) + '"><td><a href="' + esc(b.url) + '" target="_blank" rel="noopener"><strong>' + esc(b.name) + '</strong></a><div class="small muted">' + esc(b.summary) + '</div></td><td>' + esc(b.use) + '</td><td>' + esc(b.adapt) + '</td><td><a href="' + AX.buildHash('usecases', { tab: 'catalogue', bench: b.id }) + '">' + n + '</a></td></tr>';
    });
    h += '</tbody></table></div>';
    h += '<h3 class="sub">The mandate decides the result, so it is varied</h3><p style="max-width:72ch">These benchmarks have no mandates. Whoever writes them decides the outcome: a mandate written after reading the attacks will stop the attacks. Every benchmark is run under three kinds, and all three are reported.</p><div class="cards">' + E.mandates.map(function (m) {
      return '<section class="card"><h3>' + esc(m.name) + '</h3><p>' + esc(m.summary) + '</p></section>';
    }).join('') + '</div>';
    h += '<h2>Order of work</h2><div class="table-wrap"><table class="data"><thead><tr><th>Phase</th><th>What</th><th>Status</th></tr></thead><tbody>' + E.phases.map(function (ph) {
      return '<tr><td><strong>' + esc(ph.id) + '</strong> ' + esc(ph.name) + '</td><td>' + esc(ph.summary) + '</td><td><span class="tag">' + esc(ph.status === 'next' ? 'Next' : ph.status === 'later' ? 'Later' : ph.status) + '</span></td></tr>';
    }).join('') + '</tbody></table></div>';
    h += '<p style="margin-top:14px"><a href="' + AX.buildHash('specs', { doc: '60-evaluation' }) + '">The full plan</a>, including what would count against the design.</p>';
    h += '<h2 id="runs">Runs so far</h2><p style="max-width:72ch"><strong>' + nRun + ' of ' + U.length + '</strong> use cases in the catalogue has a real run. <a href="' + AX.buildHash('usecases', { tab: 'catalogue', run: 'no' }) + '">See the ' + (U.length - nRun) + ' not run yet</a>. The table below is the mortgage example: one cell per scenario and configuration that has been loaded.</p>';
    page.innerHTML = h + runsHtml;
  };
})();
